import subprocess
import time
import threading
def task_func(file_list):
    exit_codes = []
    def run_subprocess(file_path):
        try:
            process = subprocess.Popen(file_path, shell=True)
            process.wait()
            exit_codes.append(process.returncode)
        except Exception:
            exit_codes.append(-1)
    threads = []
    for file in file_list:
        thread = threading.Thread(target=run_subprocess, args=(file,))
        threads.append(thread)
        thread.start()
    for thread in threads:
        thread.join()
    return exit_codes

