import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder) or not os.path.exists(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist.', 'failed_files': []}
    failed_files = []
    for file_path in glob(os.path.join(src_folder, '*')):
        try:
            subprocess.run(['gzip', file_path], check=True)
            compressed_file = file_path + '.gz'
            shutil.move(compressed_file, dst_folder)
        except Exception:
            failed_files.append(os.path.basename(file_path))
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully.', 'failed_files': []}
    return {'success': False, 'message': 'Some files failed to compress or move.', 'failed_files': failed_files}

